(window.LADDER_CARDS=window.LADDER_CARDS||{})["17·eng"]=[{"q": "Finding how a quantity depends on others by matching the powers of their units. What is the method called?", "a": "dimensional analysis", "w": ["linear regression", "finite elements", "the method of images"], "why": "The powers of a quantity are its dimensions."}, {"q": "What are the dimensions of force in mass M, length L and time T?", "a": "M L T⁻²", "w": ["M L² T⁻²", "M L T⁻¹", "M L⁻¹ T⁻²"], "why": "Mass times acceleration."}, {"q": "Drag depends on fluid density ρ, speed v and size L. What does dimensional analysis give?", "a": "F = Cρv²L²", "w": ["F = CρvL", "F = Cρv³L", "F = Cρ²vL"], "why": "Match M, L and T on both sides."}, {"q": "High-speed drag ∝ v². By what factor does the power to overcome it grow when speed triples?", "a": "27", "w": ["3", "9", "81"], "why": "Power = Fv ∝ v³."}, {"q": "ρvL/μ. What is this number called?", "a": "the Reynolds number", "w": ["the Mach number", "the drag coefficient", "the Prandtl number"], "why": "Reynolds, 1883."}, {"q": "What does a small Reynolds number say about a flow?", "a": "viscosity dominates over inertia", "w": ["inertia dominates over viscosity", "the flow is supersonic", "the fluid has no density"], "why": "Slow, small or thick flows."}, {"q": "n physical quantities involve k independent units. How many dimensionless groups govern any law among them?", "a": "n − k", "w": ["n", "k", "n + k"], "why": "The Buckingham π theorem, 1914."}, {"q": "Drag on a small sphere in very slow flow, F = 6πμRv. What is it called?", "a": "Stokes’ law", "w": ["Bernoulli’s principle", "Newton’s drag law", "Poiseuille’s law"], "why": "Drag ∝ v, not v²."}, {"q": "A one-tenth scale model is tested in the same fluid. What speed gives the same Reynolds number?", "a": "ten times the full-size speed", "w": ["the same speed", "one tenth the speed", "√10 times the speed"], "why": "ρvL/μ fixed with L/10."}, {"q": "A model behaves like the full size when all its dimensionless groups match. What is the principle called?", "a": "similitude", "w": ["superposition", "reciprocity", "conservation of energy"], "why": "Rayleigh urged it on engineers in 1915."}];
