(window.LADDER_CARDS=window.LADDER_CARDS||{})["21·eng2"]=[{"q": "At a small heel, the upward line through the new centre of buoyancy crosses the centreline at one point. What is it called?", "a": "the metacentre", "w": ["the centre of gravity", "the centre of flotation", "the keel point"], "why": "Bouguer, Traité du navire, 1746."}, {"q": "When is a floating ship stable at small angles of heel?", "a": "when the metacentre M lies above the centre of gravity G", "w": ["when the centre of buoyancy B lies above G", "when G lies above M", "whenever the ship floats"], "why": "GM > 0."}, {"q": "How high is the metacentre above the centre of buoyancy?", "a": "BM = I/V", "w": ["BM = V/I", "BM = I·V", "BM = √(I/V)"], "why": "I the waterplane’s second moment, V the volume under water."}, {"q": "A box-shaped hull 12 m wide floats 3 m deep. What is BM?", "a": "4 m", "w": ["1 m", "48 m", "0.25 m"], "why": "For a box, BM = B²/(12T) = 144/36."}, {"q": "At a small heel θ, what is the righting arm GZ?", "a": "GM sin θ", "w": ["GM cos θ", "GM/θ", "BM sin θ"], "why": "The arm between weight and lift."}, {"q": "A ship with a large metacentric height. What is it called, and how does it roll?", "a": "stiff; a quick, jerky roll", "w": ["tender; a slow, lazy roll", "stiff; a slow, lazy roll", "tender; no roll at all"], "why": "A strong turn back gives a short roll period."}, {"q": "A box hull is made twice as wide at the same draft. By what is BM multiplied?", "a": "4", "w": ["2", "8", "16"], "why": "I grows as the width cubed, V as the width: B²."}, {"q": "Inclining test: 10 t moved 6 m across a 3000 t ship heels it until tan θ = 0.02. What is GM?", "a": "1 m", "w": ["0.02 m", "0.5 m", "20 m"], "why": "GM = w·d/(W tan θ) = 60/60."}, {"q": "A slack tank 10 m long and 6 m wide (i = 180 m⁴) on a ship of volume 3000 m³. How far does G effectively rise?", "a": "0.06 m", "w": ["0.6 m", "6 m", "0.006 m"], "why": "The free surface effect: i/V."}, {"q": "A slack tank is split lengthwise into two equal halves. What happens to its free surface effect?", "a": "it falls to a quarter", "w": ["it halves", "it is unchanged", "it vanishes"], "why": "Two tanks of half width: 2 · (1/2)³ = 1/4."}];
