(window.LADDER_CARDS=window.LADDER_CARDS||{})["28·eng"]=[{"q": "Finding where a robot’s hand is from its joint angles. What is it called?", "a": "forward kinematics", "w": ["inverse kinematics", "inverse dynamics", "path planning"], "why": "Add the links as arrows."}, {"q": "Finding the joint angles that put the hand at a given point. What is it called?", "a": "inverse kinematics", "w": ["forward kinematics", "calibration", "trajectory smoothing"], "why": "Often several answers, or none."}, {"q": "Two-link arm, a = 2, b = 1, θ₁ = 90°, θ₂ = 0. Where is the hand?", "a": "(0, 3)", "w": ["(3, 0)", "(2, 1)", "(1, 2)"], "why": "Both links point straight up."}, {"q": "Two-link arm with links 3 and 2. Which distance from the shoulder can the hand NOT reach?", "a": "0.5", "w": ["1", "3", "5"], "why": "Reach needs |a − b| ≤ r ≤ a + b."}, {"q": "A target strictly inside a two-link planar arm’s reach. How many poses reach it?", "a": "two: elbow up and elbow down", "w": ["one", "four", "infinitely many"], "why": "The triangle can be flipped."}, {"q": "The matrix of partial derivatives turning joint speeds into hand speed. What is it called?", "a": "the Jacobian", "w": ["the Hessian", "the inertia matrix", "the rotation matrix"], "why": "p′ = J θ′."}, {"q": "Two-link planar arm, a = 2, b = 3, θ₂ = 30°. What is det J?", "a": "3", "w": ["6", "5.2", "0"], "why": "det J = ab sin θ₂ = 6 · ½."}, {"q": "A pose where det J = 0, so the hand cannot move in some direction. What is it called?", "a": "a singularity", "w": ["a workspace boundary only", "a collision", "a calibration point"], "why": "Arm straight or folded."}, {"q": "The joint torques that hold a force F at the hand?", "a": "τ = Jᵀ F", "w": ["τ = J F", "τ = J⁻¹ F", "τ = F/det J"], "why": "Virtual work."}, {"q": "A standard way of writing any arm’s joints with four numbers per link, from 1955. Whose?", "a": "Denavit and Hartenberg", "w": ["Lagrange and Euler", "Newton and Leibniz", "Kalman and Bucy"], "why": "The Denavit-Hartenberg parameters."}];
