(window.LADDER_CARDS=window.LADDER_CARDS||{})["30·eng"]=[{"q": "At the best point of f under a constraint g = c, how are the gradients related?", "a": "∇f = λ∇g for some number λ", "w": ["∇f = 0", "∇f · ∇g = 0", "∇f = ∇g + λ"], "why": "Lagrange’s condition."}, {"q": "A closed cylinder of fixed volume using the least surface area. What is h/r?", "a": "2", "w": ["1", "3", "π"], "why": "As tall as it is wide."}, {"q": "An open-top cylinder (one end) of fixed volume using the least metal. What is h/r?", "a": "1", "w": ["2", "½", "4"], "why": "One end: h = r."}, {"q": "What does the Lagrange multiplier measure at the optimum?", "a": "the rate the best value changes as the constraint is loosened", "w": ["the optimum value itself", "the gradient of the constraint", "nothing: it is only a helper"], "why": "A shadow price."}, {"q": "Maximise xy subject to x + y = 20; the maximum is 100 with λ = 10. About how much does the maximum rise if the limit becomes 21?", "a": "about 10", "w": ["about 1", "about 21", "about 100"], "why": "Shadow price: 110.25 exactly."}, {"q": "First-order conditions for optimising with inequality constraints. What are they called?", "a": "the Karush-Kuhn-Tucker conditions", "w": ["the Euler-Lagrange equations", "the Cauchy-Riemann equations", "the Bellman equations"], "why": "Karush 1939; Kuhn and Tucker 1951."}, {"q": "An inequality constraint that is not tight at the optimum. What is its multiplier?", "a": "0", "w": ["1", "λ of the tight constraint", "infinite"], "why": "Complementary slackness."}, {"q": "With two goals, the set of designs not beaten in both by any other. What is it called?", "a": "the Pareto front", "w": ["the feasible region", "the null space", "the efficient market"], "why": "The trade-off curve."}, {"q": "Turning two goals into one by minimising f₁ + c·f₂ for a chosen price c. What is it called?", "a": "scalarisation (a weighted sum)", "w": ["linearisation", "normalisation", "regularisation by penalty only"], "why": "Each c picks a point on the front."}, {"q": "Who introduced the multipliers, in Mécanique analytique (1788)?", "a": "Joseph-Louis Lagrange", "w": ["Leonhard Euler", "Pierre-Simon Laplace", "Carl Friedrich Gauss"], "why": "Lagrange multipliers."}];
