(window.LADDER_CARDS=window.LADDER_CARDS||{})["32·eng2"]=[{"q": "A system where sums and multiples pass through and a delayed input gives a delayed output. What is it called?", "a": "a linear time-invariant (LTI) system", "w": ["a nonlinear system", "a time-varying system", "a chaotic system"], "why": "Fixed by one response."}, {"q": "An LTI system’s output for any input, given its impulse response h?", "a": "the convolution of the input with h", "w": ["the product of the input and h", "the sum of the input and h", "the derivative of h"], "why": "y = x * h."}, {"q": "A sinusoid of frequency f enters an LTI system. What comes out?", "a": "a sinusoid of the same frequency, scaled and shifted by H(f)", "w": ["a sinusoid of frequency 2f", "a square wave", "a sinusoid of frequency f/2"], "why": "H(f) is the frequency response."}, {"q": "RC low-pass filter with R = 1 kΩ and C = 1 µF. What is its cutoff frequency?", "a": "about 159 Hz", "w": ["about 1000 Hz", "about 6.3 Hz", "about 1 Hz"], "why": "1/(2πRC) with RC = 1 ms."}, {"q": "At the cutoff frequency of an RC low-pass filter, what is |H|?", "a": "1/√2, about −3 dB", "w": ["½, about −6 dB", "0", "1"], "why": "|H| = 1/√(1 + 1)."}, {"q": "An RC low-pass filter at a frequency where 2πfτ = 3. What is |H|?", "a": "about 0.32", "w": ["about 0.25", "about 0.33", "about 0.1"], "why": "1/√(1 + 9)."}, {"q": "Two filters in a chain give −20 dB and −15 dB at some frequency. What does the chain give?", "a": "−35 dB", "w": ["−300 dB", "−17.5 dB", "−5 dB"], "why": "Gains multiply; decibels add."}, {"q": "Far above its cutoff, a first-order RC filter falls by how much per tenfold rise in frequency?", "a": "20 dB", "w": ["3 dB", "6 dB", "40 dB"], "why": "20 dB per decade, read on a Bode plot."}, {"q": "y_n = 0.8y_{n−1} + 0.2x_n. What is its gain at half the sampling rate?", "a": "about 0.11", "w": ["0.2", "0.8", "1"], "why": "(1 − a)/(1 + a) = 0.2/1.8."}, {"q": "A digital filter whose output feeds back into itself, so its click response never quite ends. What is it called?", "a": "an infinite impulse response (IIR) filter", "w": ["a finite impulse response (FIR) filter", "a median filter", "an all-pass delay line"], "why": "First-order IIR smoothing."}];
