(window.LADDER_CARDS=window.LADDER_CARDS||{})["33·eng2"]=[{"q": "Heat conducts across a still air layer 2 mm thick, k = 0.025 W/(m·K), temperature difference 20 K. What is the heat flow?", "a": "250 W/m²", "w": ["1 W/m²", "25 W/m²", "1000 W/m²"], "why": "q = kΔT/δ."}, {"q": "The thin layer of slowed fluid next to a surface. What is it called?", "a": "the boundary layer", "w": ["the thermocline", "the wake", "the free stream"], "why": "Prandtl, 1904."}, {"q": "In smooth flow along a plate, the wind is made 9 times faster. What happens to the boundary layer’s thickness?", "a": "it becomes a third", "w": ["it becomes a ninth", "it triples", "it is unchanged"], "why": "δ ∝ √(νx/U)."}, {"q": "In smooth flow, the wind speed is quadrupled. What happens to the heat transfer coefficient h?", "a": "it doubles", "w": ["it quadruples", "it halves", "it rises sixteenfold"], "why": "h ∝ √U."}, {"q": "q = hΔT, heat loss proportional to the temperature difference. What is the law called?", "a": "Newton’s law of cooling", "w": ["Fourier’s law", "Stefan-Boltzmann law", "Fick’s law"], "why": "Newton, 1701."}, {"q": "A 30 W device must stay within 30 K of the air, with h = 25 W/(m²·K). What area is needed?", "a": "0.04 m²", "w": ["0.4 m²", "0.004 m²", "1 m²"], "why": "A = Q/(hΔT)."}, {"q": "Radiation from a surface near 300 K, linearised: about how big is its effective h?", "a": "about 6 W/(m²·K)", "w": ["about 0.06 W/(m²·K)", "about 60 W/(m²·K)", "about 600 W/(m²·K)"], "why": "4σT³ ≈ 4 · 5.67 × 10⁻⁸ · 2.7 × 10⁷."}, {"q": "hL/k, comparing convection with conduction across a length L. What is the number called?", "a": "the Nusselt number", "w": ["the Reynolds number", "the Prandtl number", "the Biot number of the fluid"], "why": "Nusselt, 1915."}, {"q": "Heat carried away by warm fluid rising on its own, with no fan. What is it called?", "a": "natural (free) convection", "w": ["forced convection", "conduction", "radiation"], "why": "About 5 W/(m²·K) in still air."}, {"q": "Why does cold water chill a body faster than cold air at the same temperature?", "a": "water conducts heat far better, so h is much larger", "w": ["water is always colder than air", "water has no boundary layer", "air conducts better but holds less"], "why": "About twenty times the conductivity."}];
